// The crab waist's PHYSICS content, which symplecticity cannot gate.
//
// WHY THIS FILE EXISTS. Every existing crab-waist check is a symplecticity
// check, and symplecticity is blind to whether g(x) is right. The map is
// generated by S2 = q.P + (1/2) g(x) Py^2 for ANY g, so
//
//     fraction = 1      exactly symplectic
//     fraction = 2      exactly symplectic
//     fraction = -1     exactly symplectic
//     a cubic term      exactly symplectic
//
// all pass identically. A factor of two in g -- which is what declaring the
// HALF crossing angle instead of the full one produces -- would sail through
// every gate in the repo while delivering, by measurement, exactly zero net
// luminosity effect. OPEN_ITEMS 3.2 recorded that the waist had no luminosity
// gate; this file gates the thing the luminosity gate would have been proxying
// for, and does it in microseconds instead of core-hours.
//
// THE ESTABLISHED FORM. g(x) = -fraction * x / tan(theta_full), with
// fraction = 1 the ideal waist. The two beams are tilted theta/2 in OPPOSITE
// senses, so a particle and the opposing beam's axis close at the FULL angle
// and the meeting point is at x/theta_full -- not x/(theta/2), which is the
// factor-of-two trap. Confirmed three independent ways: static intersection,
// a boost to the head-on frame, and FEEBL's own slice pairing; and measured,
// with the luminosity curve mirror-symmetric about fraction = 1.0 and
// fraction = 2.0 landing back on the no-waist baseline.

#include "gpgeom/maps.hpp"
#include "gpgeom/phase_space.hpp"

#include <cmath>
#include <cstdio>

using gpgeom::CrabWaistMap;
using gpgeom::Matrix6;
using gpgeom::PhaseSpace6D;

static int failures = 0;

static void ok(bool cond, const char* what)
{
  std::printf("  %-62s %s\n", what, cond ? "PASS" : "FAIL");
  if (!cond) failures++;
}

static double defect(const CrabWaistMap& m, const PhaseSpace6D& at)
{
  const Matrix6 j = gpgeom::numerical_jacobian(
      [&](PhaseSpace6D& q) { m.apply(q); }, at, 2.0e-7);
  return gpgeom::symplectic_defect_inf_norm(j);
}

int main()
{
  std::printf("=== g(x) is the ideal waist: -fraction*x/tan(theta_full) ===\n");

  // Real working points, not round numbers: ILC's 14 mrad and FCC-ee's 30.
  const double thetas[3] = {0.014, 0.030, 0.002};
  const double fracs[3]  = {1.0, 0.5, 2.0};
  double worst_g = 0.0, worst_dg = 0.0;

  for (int it = 0; it < 3; it++)
    for (int ifr = 0; ifr < 3; ifr++)
      {
        const double th = thetas[it], fr = fracs[ifr];
        const CrabWaistMap m(th, fr);
        const double want_slope = -fr / std::tan(th);
        for (int k = -3; k <= 3; k++)
          {
            const double x = 1.0e-5 * k;
            const double want = want_slope * x;
            const double got = m.g(x);
            const double scale = std::fabs(want) > 1e-30 ? std::fabs(want) : 1.0;
            const double r = std::fabs(got - want) / scale;
            if (r > worst_g) worst_g = r;
            const double rd = std::fabs(m.dg_dx(x) - want_slope)
                            / std::fabs(want_slope);
            if (rd > worst_dg) worst_dg = rd;
          }
      }
  std::printf("      worst relative error: g %.3e, dg/dx %.3e\n",
              worst_g, worst_dg);
  ok(worst_g < 1.0e-13, "g(x) equals -fraction*x/tan(theta) at every point");
  ok(worst_dg < 1.0e-13, "dg/dx equals -fraction/tan(theta)");

  // The trap, stated as a number. Declaring theta/2 where theta was meant
  // doubles |g'|, which is identical to fraction = 2.
  {
    const CrabWaistMap right(0.030, 1.0);   // full angle, correct
    const CrabWaistMap wrong(0.015, 1.0);   // half angle, the mistake
    const double ratio = wrong.dg_dx(0.0) / right.dg_dx(0.0);
    std::printf("      declaring the HALF angle scales g' by %.4f\n", ratio);
    ok(std::fabs(ratio - 2.0) < 1.0e-3,
       "the half-angle mistake is exactly a factor of two in g'");
    // Not EXACTLY two, and the difference is worth knowing. tan is nonlinear:
    //   1/tan(t/2) over 2/tan(t)  =  1 + t^2/4 + O(t^4)
    // so at 30 mrad the half-angle mistake is 2.00023 rather than 2.00000. It
    // is operationally the same as waist_fraction = 2 -- 2e-4 is far below any
    // measurement here -- but the two are not identical, and an assertion
    // demanding they agree to machine precision fails for a real reason.
    const CrabWaistMap f2(0.030, 2.0);
    const double rel = std::fabs(wrong.dg_dx(0.0) - f2.dg_dx(0.0))
                     / std::fabs(f2.dg_dx(0.0));
    const double predicted = 0.030 * 0.030 / 4.0;
    std::printf("      vs waist_fraction=2: %.3e apart, t^2/4 predicts %.3e\n",
                rel, predicted);
    ok(std::fabs(rel - predicted) < 0.05 * predicted,
       "and differs from waist_fraction = 2 by exactly t^2/4");
  }

  std::printf("\n=== the map is what the generating function says ===\n");
  {
    const double th = 0.014, fr = 1.0;
    const CrabWaistMap m(th, fr);
    PhaseSpace6D p;
    p.x = 3.0e-6; p.px = 1.1e-5; p.y = -2.0e-6; p.py = 4.0e-6;
    p.zeta = 1.5e-4; p.delta = 7.0e-4;
    const PhaseSpace6D in = p;
    m.apply(p);
    const double gx = m.g(in.x), dg = m.dg_dx(in.x);
    ok(std::fabs(p.y - (in.y + gx * in.py)) < 1e-18, "y += g(x) * py");
    ok(std::fabs(p.px - (in.px - 0.5 * dg * in.py * in.py)) < 1e-18,
       "px -= (1/2) g'(x) py^2, the companion");
    ok(p.py == in.py && p.delta == in.delta && p.zeta == in.zeta
       && p.x == in.x, "and nothing else moves");
  }

  // THE NON-VACUITY PROOF, and the reason this file is separate from the
  // symplecticity suite: the wrong maps are just as symplectic as the right
  // one, so no symplecticity test could ever have caught them.
  std::printf("\n=== why symplecticity cannot do this job ===\n");
  {
    PhaseSpace6D at;
    at.x = 2.0e-6; at.px = 5.0e-6; at.y = 1.0e-6; at.py = 3.0e-6;
    at.zeta = 1.0e-4; at.delta = 5.0e-4;
    const double d1 = defect(CrabWaistMap(0.030, 1.0), at);   // correct
    const double d2 = defect(CrabWaistMap(0.030, 2.0), at);   // twice
    const double d3 = defect(CrabWaistMap(0.030, -1.0), at);  // anti-waist
    const double d4 = defect(CrabWaistMap(0.030, 1.0, 1.0e6), at);  // cubic
    std::printf("      defects: correct %.2e  f=2 %.2e  f=-1 %.2e  cubic %.2e\n",
                d1, d2, d3, d4);
    const double tol = 1.0e-9;
    ok(d1 < tol && d2 < tol && d3 < tol && d4 < tol,
       "a doubled, a reversed and a cubic g are ALL exactly symplectic");
    std::printf("      -- so the value assertions above are the ONLY gate on g\n");
  }

  std::printf("\n  %d failure(s)\n", failures);
  return failures == 0 ? 0 : 1;
}
